{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "In patients with B-cell lymphomas or advanced solid tumors, tazemetostat had a median absolute oral bioavailability of 31.8% (range 20.2–49.8%) after 800 mg tablets in the fasted state, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "In healthy subjects, tolvaptan had a mean absolute oral bioavailability of 56% (range 42–80%) after a 30 mg oral tablet versus IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "In healthy volunteers, acalabrutinib had a geometric mean absolute oral bioavailability of 25.3% after a 100 mg oral capsule versus IV microtracer, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All supplied human absolute bioavailability values are above the 20% threshold (25.3–73%), including a fasted-state measurement of 31.8%; therefore the query is predicted to have high oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "Only one supplied record explicitly states a fasted-state condition; other records do not specify prandial state.",
    "Some supporting records are qualitative or from non-human models, but the numeric human absolute bioavailability records are sufficient for the prediction."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

